def three_sum(nums):
    n, found = len(nums), set()
    for i in range(n):
        seen = set()                   # values between i and j
        for j in range(i + 1, n):
            need = -nums[i] - nums[j]
            if need in seen:
                found.add(tuple(sorted((nums[i], nums[j], need))))
            seen.add(nums[j])
    return [list(t) for t in found]

