def trap(height):
    n = len(height)
    if n == 0:
        return 0
    pre, suf = [0] * n, [0] * n
    pre[0], suf[-1] = height[0], height[-1]
    for i in range(1, n):
        pre[i] = max(pre[i - 1], height[i])        # max of height[:i+1]
    for i in range(n - 2, -1, -1):
        suf[i] = max(suf[i + 1], height[i])        # max of height[i:]
    return sum(min(pre[i], suf[i]) - height[i] for i in range(n))

