def two_sum(numbers, target):
    n = len(numbers)
    for i in range(n):
        need = target - numbers[i]
        j = bisect_left(numbers, need, i + 1, n)   # search right of i only
        if j < n and numbers[j] == need:
            return [i + 1, j + 1]
